import { MaterialIcons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { View, Text, StyleSheet, ScrollView, Pressable } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { typography, spacing, borderRadius, shadows } from '../../constants/designTokens';
import { useAuthStore, useHostelStore } from '../../src/stores';
import { useEffect } from 'react';

// Admin Orange & Cream Theme
const THEME = {
  primary: '#EA580C',      // Burnt orange
  primaryDark: '#C2410C',  // Darker burnt orange  
  primaryLight: '#F97316', // Bright orange
  cream: '#FFFBF5',        // Warm cream
  creamLight: '#FFFDF9',   // Off-white
  white: '#FFFFFF',
  textPrimary: '#1F2937',
  textSecondary: '#6B7280',
  textMuted: '#9CA3AF',
  textInverse: '#FFFFFF',
  success: '#10B981',
  error: '#EF4444',
  warning: '#F59E0B',
  border: '#FED7AA',
};

export default function AdminDashboard() {
  const router = useRouter();
  const { user } = useAuthStore();
  const { summary, fetchSummary } = useHostelStore();

  useEffect(() => {
    fetchSummary('hostel-001');
  }, []);

  const stats = [
    { label: 'Total Beds', value: summary?.totalBeds || 8, icon: 'bed', color: THEME.primary },
    { label: 'Occupied', value: summary?.occupiedBeds || 3, icon: 'people', color: THEME.success },
    { label: 'Available', value: summary?.availableBeds || 5, icon: 'check-circle', color: THEME.warning },
    { label: 'Revenue', value: '₹24K', icon: 'trending-up', color: THEME.primaryDark },
  ];

  const menuItems = [
    { 
      icon: 'apartment', 
      label: 'Infrastructure', 
      description: 'Manage floors, rooms & beds',
      route: '/admin/infrastructure',
      gradient: [THEME.primary, THEME.primaryLight] as const,
    },
    { 
      icon: 'people', 
      label: 'Tenants', 
      description: 'Manage tenant records',
      route: '/admin/tenants',
      gradient: [THEME.primaryLight, '#FB923C'] as const,
    },
    { 
      icon: 'receipt-long', 
      label: 'Billing', 
      description: 'Payments & invoices',
      route: '/admin/billing',
      gradient: [THEME.warning, '#FBBF24'] as const,
    },
    { 
      icon: 'restaurant-menu', 
      label: 'Food Menu', 
      description: 'Daily meal planning',
      route: '/admin/Menu',
      gradient: [THEME.success, '#34D399'] as const,
    },
    { 
      icon: 'campaign', 
      label: 'Announcements', 
      description: 'Send notifications',
      route: '/admin/announcements',
      gradient: ['#0EA5E9', '#38BDF8'] as const,
    },
    { 
      icon: 'settings', 
      label: 'Settings', 
      description: 'App configuration',
      route: '/admin/profile',
      gradient: ['#64748B', '#94A3B8'] as const,
    },
  ];

  return (
    <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
      {/* Header */}
      <LinearGradient
        colors={[THEME.primary, THEME.primaryDark]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <View>
            <Text style={styles.welcomeText}>Welcome back,</Text>
            <Text style={styles.userName}>{user?.name || 'Admin'}</Text>
            <View style={styles.hostelBadge}>
              <MaterialIcons name="business" size={14} color={THEME.border} />
              <Text style={styles.hostelText}>Sunrise PG</Text>
            </View>
          </View>
          <Pressable style={styles.notificationBtn}>
            <MaterialIcons name="notifications" size={24} color={THEME.white} />
          </Pressable>
        </View>
      </LinearGradient>

      {/* Stats Grid */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Overview</Text>
        <View style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <View key={index} style={styles.statCard}>
              <View style={[styles.statIcon, { backgroundColor: stat.color + '15' }]}>
                <MaterialIcons name={stat.icon as any} size={20} color={stat.color} />
              </View>
              <Text style={styles.statValue}>{stat.value}</Text>
              <Text style={styles.statLabel}>{stat.label}</Text>
            </View>
          ))}
        </View>
      </View>

      {/* Quick Actions */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Management</Text>
        <View style={styles.menuGrid}>
          {menuItems.map((item, index) => (
            <Pressable
              key={index}
              style={({ pressed }) => [
                styles.menuCard,
                pressed && styles.cardPressed
              ]}
              onPress={() => router.push(item.route as never)}
            >
              <LinearGradient
                colors={item.gradient}
                start={{ x: 0, y: 0 }}
                end={{ x: 1, y: 1 }}
                style={styles.menuIcon}
              >
                <MaterialIcons name={item.icon as any} size={24} color={THEME.white} />
              </LinearGradient>
              <View style={styles.menuInfo}>
                <Text style={styles.menuLabel}>{item.label}</Text>
                <Text style={styles.menuDesc}>{item.description}</Text>
              </View>
              <MaterialIcons name="chevron-right" size={20} color={THEME.textMuted} />
            </Pressable>
          ))}
        </View>
      </View>

      {/* Recent Activity */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Recent Activity</Text>
        <View style={styles.activityCard}>
          <View style={styles.activityItem}>
            <View style={[styles.activityDot, { backgroundColor: THEME.success }]} />
            <View style={styles.activityContent}>
              <Text style={styles.activityText}>New tenant registered</Text>
              <Text style={styles.activityTime}>2 hours ago</Text>
            </View>
          </View>
          <View style={styles.activityDivider} />
          <View style={styles.activityItem}>
            <View style={[styles.activityDot, { backgroundColor: THEME.warning }]} />
            <View style={styles.activityContent}>
              <Text style={styles.activityText}>Payment received - ₹8,000</Text>
              <Text style={styles.activityTime}>5 hours ago</Text>
            </View>
          </View>
          <View style={styles.activityDivider} />
          <View style={styles.activityItem}>
            <View style={[styles.activityDot, { backgroundColor: THEME.primary }]} />
            <View style={styles.activityContent}>
              <Text style={styles.activityText}>Maintenance request completed</Text>
              <Text style={styles.activityTime}>1 day ago</Text>
            </View>
          </View>
        </View>
      </View>
    </ScrollView>
  );
}

