// app/admin/hostels.tsx
import { MaterialIcons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { useState, useEffect } from 'react';
import { View, Text, StyleSheet, ScrollView, TouchableOpacity, Modal, TextInput, Alert } from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { typography, spacing, borderRadius, shadows } from '../../constants/designTokens';
import { useHostelStore, useAuthStore } from '../../src/stores';

// Admin Orange & Cream Theme
const THEME = {
  primary: '#EA580C',
  primaryDark: '#C2410C',
  primaryLight: '#F97316',
  cream: '#FFFBF5',
  creamLight: '#FFFDF9',
  white: '#FFFFFF',
  textPrimary: '#1F2937',
  textSecondary: '#6B7280',
  textMuted: '#9CA3AF',
  textInverse: '#FFFFFF',
  success: '#10B981',
  error: '#EF4444',
  warning: '#F59E0B',
  border: '#FED7AA',
};

// Extended Hostel Type for UI
interface HostelUI {
  id: string;
  name: string;
  address: string;
  city: string;
  totalBeds: number;
  availableBeds: number;
  occupiedBeds: number;
}

// Add Hostel Modal
const AddHostelModal = ({
  visible,
  onClose,
  onAddHostel,
}: {
  visible: boolean;
  onClose: () => void;
  onAddHostel: (hostel: Omit<HostelUI, 'id' | 'totalBeds' | 'availableBeds' | 'occupiedBeds'>) => void;
}) => {
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');

  const handleAdd = () => {
    if (!name || !address || !city) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }
    onAddHostel({ name, address, city });
    setName('');
    setAddress('');
    setCity('');
    onClose();
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View style={styles.modalOverlay}>
        <View style={styles.modalContent}>
          <View style={styles.modalHeader}>
            <Text style={styles.modalTitle}>Add New Hostel</Text>
            <TouchableOpacity onPress={onClose} style={styles.closeBtn}>
              <MaterialIcons name="close" size={24} color={THEME.textSecondary} />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Hostel Name *</Text>
              <TextInput
                placeholder="Enter hostel name"
                placeholderTextColor={THEME.textMuted}
                value={name}
                onChangeText={setName}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Address *</Text>
              <TextInput
                placeholder="Enter complete address"
                placeholderTextColor={THEME.textMuted}
                value={address}
                onChangeText={setAddress}
                multiline
                numberOfLines={2}
                style={[styles.input, styles.textArea]}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>City *</Text>
              <TextInput
                placeholder="Enter city"
                placeholderTextColor={THEME.textMuted}
                value={city}
                onChangeText={setCity}
                style={styles.input}
              />
            </View>
          </ScrollView>

          <View style={styles.modalButtons}>
            <TouchableOpacity onPress={onClose} style={[styles.modalBtn, styles.cancelBtn]}>
              <Text style={styles.cancelBtnText}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={handleAdd} style={[styles.modalBtn, styles.addBtn]}>
              <Text style={styles.addBtnText}>Add Hostel</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default function HostelsScreen() {
  const router = useRouter();
  const { user } = useAuthStore();
  const { hostels, fetchHostels, setCurrentHostel, createHostel } = useHostelStore();
  const [modalVisible, setModalVisible] = useState(false);
  const [selectedHostelId, setSelectedHostelId] = useState<string | null>(null);

  useEffect(() => {
    fetchHostels();
  }, [fetchHostels]);

  // Auto-redirect if there's only one hostel
  useEffect(() => {
    if (hostels.length === 1) {
      const hostel = hostels[0];
      setCurrentHostel(hostel);
      setSelectedHostelId(hostel.id);
      // Small delay to show the hostel card briefly before redirecting
      const timer = setTimeout(() => {
        router.push('/admin/Dashboard' as never);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [hostels, setCurrentHostel, router]);

  const handleHostelSelect = (hostel: any) => {
    setCurrentHostel(hostel);
    setSelectedHostelId(hostel.id);
    // Redirect to Dashboard after selecting hostel
    router.push('/admin/Dashboard' as never);
  };

  const handleAddHostel = async (hostelData: any) => {
    try {
      await createHostel({
        ...hostelData,
        shortStayEnabled: false,
      });
      Alert.alert('Success', 'Hostel added successfully');
    } catch (error) {
      Alert.alert('Error', 'Failed to add hostel');
    }
  };

  const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <LinearGradient
        colors={[THEME.primary, THEME.primaryDark]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <View>
            <Text style={styles.welcomeText}>My Hostels</Text>
            <Text style={styles.userName}>{user?.name || 'Admin'}</Text>
          </View>
          <View style={styles.hostelCountBadge}>
            <MaterialIcons name="apartment" size={16} color={THEME.border} />
            <Text style={styles.hostelCountText}>{hostels.length} Hostels</Text>
          </View>
        </View>
      </LinearGradient>

      <ScrollView style={styles.scrollView} contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        {/* Add Hostel Button */}
        <TouchableOpacity onPress={() => setModalVisible(true)} style={styles.addHostelBtn}>
          <MaterialIcons name="add-business" size={20} color={THEME.textInverse} />
          <Text style={styles.addHostelBtnText}>Add New Hostel</Text>
        </TouchableOpacity>

        <AddHostelModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          onAddHostel={handleAddHostel}
        />

        {/* Hostels List */}
        <View style={styles.hostelsSection}>
          <Text style={styles.sectionTitle}>
            {hostels.length} Hostel{hostels.length !== 1 ? 's' : ''}
          </Text>

          {hostels.length > 0 ? (
            hostels.map((hostel) => (
              <TouchableOpacity
                key={hostel.id}
                style={[
                  styles.hostelCard,
                  selectedHostelId === hostel.id && styles.hostelCardSelected,
                ]}
                onPress={() => handleHostelSelect(hostel)}
              >
                <View style={styles.hostelHeader}>
                  <View style={styles.hostelInfo}>
                    <View style={[
                      styles.hostelAvatar,
                      selectedHostelId === hostel.id && styles.hostelAvatarSelected,
                    ]}>
                      <Text style={styles.hostelAvatarText}>{getInitials(hostel.name)}</Text>
                    </View>
                    <View style={styles.hostelDetails}>
                      <Text style={styles.hostelName}>{hostel.name}</Text>
                      <Text style={styles.hostelLocation}>
                        <MaterialIcons name="location-on" size={12} color={THEME.textMuted} />
                        {hostel.city}
                      </Text>
                    </View>
                  </View>
                  {selectedHostelId === hostel.id && (
                    <View style={styles.selectedBadge}>
                      <MaterialIcons name="check-circle" size={20} color={THEME.success} />
                    </View>
                  )}
                </View>

                <View style={styles.hostelStats}>
                  <View style={styles.statItem}>
                    <Text style={styles.statValue}>{(hostel as any).totalBeds || 0}</Text>
                    <Text style={styles.statLabel}>Total Beds</Text>
                  </View>
                  <View style={styles.statDivider} />
                  <View style={styles.statItem}>
                    <Text style={[styles.statValue, { color: THEME.success }]}>
                      {(hostel as any).availableBeds || 0}
                    </Text>
                    <Text style={styles.statLabel}>Available</Text>
                  </View>
                  <View style={styles.statDivider} />
                  <View style={styles.statItem}>
                    <Text style={[styles.statValue, { color: THEME.primary }]}>
                      {(hostel as any).occupiedBeds || 0}
                    </Text>
                    <Text style={styles.statLabel}>Occupied</Text>
                  </View>
                </View>

                <View style={styles.hostelAddress}>
                  <MaterialIcons name="location-city" size={14} color={THEME.textSecondary} />
                  <Text style={styles.addressText} numberOfLines={1}>{hostel.address}</Text>
                </View>

                <TouchableOpacity
                  style={styles.manageBtn}
                  onPress={() => {
                    setCurrentHostel(hostel);
                    router.push('/admin/Dashboard' as never);
                  }}
                >
                  <Text style={styles.manageBtnText}>Manage Hostel</Text>
                  <MaterialIcons name="arrow-forward" size={16} color={THEME.primary} />
                </TouchableOpacity>
              </TouchableOpacity>
            ))
          ) : (
            <View style={styles.emptyState}>
              <MaterialIcons name="apartment" size={48} color={THEME.textMuted} />
              <Text style={styles.emptyTitle}>No hostels found</Text>
              <Text style={styles.emptySubtitle}>Add your first hostel to get started</Text>
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  );
}

