  };

  // Assign bed to selected tenant
  const handleSelectTenant = async (tenantId: string) => {
    if (!selectedBed) return;

    try {
      await assignBed(selectedBed.id, tenantId);
      if (selectedRoom) {
        await fetchBeds(selectedRoom);
      }
      setTenantModalVisible(false);
      setSelectedBed(null);
      Alert.alert('Success', `Bed ${selectedBed.bedNumber} assigned successfully`);
    } catch (error) {
      Alert.alert('Error', 'Failed to assign bed');
    }
  };

  // Close all modals
  const closeBedModal = () => {
    setBedModalVisible(false);
    setSelectedBed(null);
  };

  const closeTenantModal = () => {
    setTenantModalVisible(false);
    setSelectedBed(null);
  };

  // Get available tenants (those without an assigned bed)
  const getAvailableTenants = () => {
    const assignedBedIds = new Set(beds.filter(b => b.tenantId).map(b => b.tenantId));
    return tenants.filter(t => !assignedBedIds.has(t.id) && t.status === 'active');
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <LinearGradient
        colors={[THEME.primary, THEME.primaryDark]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.header}
      >
        <Pressable onPress={() => router.back()} style={styles.backBtn}>
          <MaterialIcons name="arrow-back" size={24} color={THEME.textInverse} />
        </Pressable>
        <Text style={styles.headerTitle}>Infrastructure</Text>
        <View style={styles.placeholder} />
      </LinearGradient>

      <ScrollView style={styles.content} showsVerticalScrollIndicator={false}>
        {/* Floors Section */}
        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>Floors</Text>
            <Pressable style={styles.addBtn} onPress={() => openModal('floor')}>
              <MaterialIcons name="add" size={20} color={THEME.textInverse} />
              <Text style={styles.addBtnText}>Add Floor</Text>
            </Pressable>
          </View>

          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.horizontalScroll}>
            {floors.map((floor) => (
              <Pressable
                key={floor.id}
                style={[
                  styles.floorCard,
                  selectedFloor === floor.id && styles.floorCardActive
                ]}
                onPress={() => setSelectedFloor(floor.id)}
              >
                <MaterialIcons 
                  name="apartment" 
                  size={24} 
                  color={selectedFloor === floor.id ? THEME.textInverse : THEME.primary} 
                />
                <Text style={[
                  styles.floorText,
                  selectedFloor === floor.id && styles.floorTextActive
                ]}>
                  {floor.name || `Floor ${floor.floorNumber}`}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
        </View>

        {/* Rooms Section */}
        {selectedFloor && (
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Rooms</Text>
              <Pressable style={styles.addBtn} onPress={() => openModal('room')}>
                <MaterialIcons name="add" size={20} color={THEME.textInverse} />
                <Text style={styles.addBtnText}>Add Room</Text>
              </Pressable>
            </View>

            <View style={styles.roomsGrid}>
              {rooms.map((room) => (
                <Pressable
                  key={room.id}
                  style={[
                    styles.roomCard,
                    selectedRoom === room.id && styles.roomCardActive
                  ]}
                  onPress={() => setSelectedRoom(room.id)}
                >
                  <MaterialIcons 
                    name="meeting-room" 
                    size={20} 
                    color={selectedRoom === room.id ? THEME.textInverse : THEME.primary} 
                  />
                  <Text style={[
                    styles.roomText,
                    selectedRoom === room.id && styles.roomTextActive
                  ]}>
                    Room {room.roomNumber}
                  </Text>
                </Pressable>
              ))}
            </View>
          </View>
        )}

        {/* Beds Section */}
        {selectedRoom && (
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Beds</Text>
              <Pressable style={styles.addBtn} onPress={() => openModal('bed')}>
                <MaterialIcons name="add" size={20} color={THEME.textInverse} />
                <Text style={styles.addBtnText}>Add Bed</Text>
              </Pressable>
            </View>

            <View style={styles.bedsGrid}>
              {beds.map((bed) => (
                <Pressable
                  key={bed.id}
                  style={[
                    styles.bedCard,
                    bed.status === 'occupied' && styles.bedCardOccupied,
                    bed.status === 'available' && styles.bedCardAvailable,
                  ]}
                  onPress={() => handleBedPress(bed)}
                >
                  <MaterialIcons 
                    name="bed" 
                    size={20} 
                    color={bed.status === 'occupied' ? THEME.error : THEME.success} 
                  />
                  <Text style={styles.bedText}>Bed {bed.bedNumber}</Text>
                  <Text style={[
                    styles.bedStatus,
                    { color: bed.status === 'occupied' ? THEME.error : THEME.success }
                  ]}>
                    {bed.status}
                  </Text>
                  {bed.tenant && (
                    <View style={styles.tenantInfo}>
                      <MaterialIcons name="person" size={12} color={THEME.textSecondary} />
                      <Text style={styles.tenantName} numberOfLines={1}>
                        {bed.tenant.name}
                      </Text>
                    </View>
                  )}
                  <Text style={styles.bedPrice}>₹{bed.price}</Text>
                </Pressable>
              ))}
            </View>
          </View>
        )}
      </ScrollView>

      {/* Add Modal */}
      <Modal
        animationType="slide"
        transparent={true}
        visible={modalVisible}
        onRequestClose={() => setModalVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            <Text style={styles.modalTitle}>
              Add {modalType === 'floor' ? 'Floor' : modalType === 'room' ? 'Room' : 'Bed'}
            </Text>

            <TextInput
              style={styles.input}
              placeholder={
                modalType === 'floor' ? 'Floor Number' : 
                modalType === 'room' ? 'Room Number' : 'Bed Number'
              }
              placeholderTextColor={THEME.textMuted}
              value={inputValue}
              onChangeText={setInputValue}
              keyboardType={modalType === 'floor' ? 'numeric' : 'default'}
            />

            {modalType === 'floor' && (
              <TextInput
                style={styles.input}
                placeholder="Floor Name (optional)"
                placeholderTextColor={THEME.textMuted}
                value={inputValue2}
                onChangeText={setInputValue2}
              />
            )}

            {modalType === 'bed' && (
              <TextInput
                style={styles.input}
                placeholder="Price (₹)"
                placeholderTextColor={THEME.textMuted}
                value={inputValue2}
                onChangeText={setInputValue2}
                keyboardType="numeric"
              />
            )}

            <View style={styles.modalButtons}>
              <Pressable 
                style={[styles.modalBtn, styles.cancelBtn]} 
                onPress={() => setModalVisible(false)}
