                <Text style={styles.confirmBtnText}>Add</Text>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

      {/* Bed Action Modal */}
      <Modal
        animationType="slide"
        transparent={true}
        visible={bedModalVisible}
        onRequestClose={closeBedModal}
      >
        <View style={styles.modalOverlay}>
          <View style={styles.modalContent}>
            {selectedBed && (
              <>
                <View style={styles.bedModalHeader}>
                  <MaterialIcons 
                    name="bed" 
                    size={32} 
                    color={selectedBed.status === 'occupied' ? THEME.error : THEME.success} 
                  />
                  <Text style={styles.bedModalTitle}>Bed {selectedBed.bedNumber}</Text>
                  <Text style={[
                    styles.bedModalStatus,
                    { color: selectedBed.status === 'occupied' ? THEME.error : THEME.success }
                  ]}>
                    {selectedBed.status.toUpperCase()}
                  </Text>
                </View>

                {selectedBed.tenant && (
                  <View style={styles.tenantDetailCard}>
                    <Text style={styles.tenantDetailLabel}>Current Tenant</Text>
                    <Text style={styles.tenantDetailName}>{selectedBed.tenant.name}</Text>
                    <Text style={styles.tenantDetailPhone}>{selectedBed.tenant.phone}</Text>
                  </View>
                )}

                <View style={styles.actionButtons}>
                  {selectedBed.status === 'occupied' ? (
                    <Pressable 
                      style={[styles.actionBtn, styles.vacateBtn]} 
                      onPress={handleVacateBed}
                    >
                      <MaterialIcons name="logout" size={20} color={THEME.textInverse} />
                      <Text style={styles.actionBtnText}>Vacate Bed</Text>
                    </Pressable>
                  ) : (
                    <Pressable 
                      style={[styles.actionBtn, styles.assignBtn]} 
                      onPress={handleAssignBed}
                    >
                      <MaterialIcons name="person-add" size={20} color={THEME.textInverse} />
                      <Text style={styles.actionBtnText}>Assign to Tenant</Text>
                    </Pressable>
                  )}

                  <Pressable 
                    style={[styles.actionBtn, styles.cancelActionBtn]} 
                    onPress={closeBedModal}
                  >
                    <Text style={styles.cancelActionBtnText}>Cancel</Text>
                  </Pressable>
                </View>
              </>
            )}
          </View>
        </View>
      </Modal>

      {/* Tenant Selection Modal */}
      <Modal
        animationType="slide"
        transparent={true}
        visible={tenantModalVisible}
        onRequestClose={closeTenantModal}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, styles.tenantModalContent]}>
            <View style={styles.tenantModalHeader}>
              <Text style={styles.modalTitle}>Select Tenant</Text>
              <Pressable onPress={closeTenantModal}>
                <MaterialIcons name="close" size={24} color={THEME.textSecondary} />
              </Pressable>
            </View>

            <Text style={styles.tenantModalSubtitle}>
              Assigning Bed {selectedBed?.bedNumber}
            </Text>

            <ScrollView style={styles.tenantList} showsVerticalScrollIndicator={false}>
              {getAvailableTenants().length === 0 ? (
                <View style={styles.emptyState}>
                  <MaterialIcons name="people-outline" size={48} color={THEME.textMuted} />
                  <Text style={styles.emptyStateText}>No available tenants</Text>
                  <Text style={styles.emptyStateSubtext}>
                    All tenants already have beds assigned
                  </Text>
                </View>
              ) : (
                getAvailableTenants().map((tenant) => (
                  <Pressable
                    key={tenant.id}
                    style={styles.tenantItem}
                    onPress={() => handleSelectTenant(tenant.id)}
                  >
                    <View style={styles.tenantAvatar}>
                      <Text style={styles.tenantAvatarText}>
                        {tenant.name.charAt(0).toUpperCase()}
                      </Text>
                    </View>
                    <View style={styles.tenantItemInfo}>
                      <Text style={styles.tenantItemName}>{tenant.name}</Text>
                      <Text style={styles.tenantItemPhone}>{tenant.phone}</Text>
                    </View>
                    <MaterialIcons name="chevron-right" size={24} color={THEME.textMuted} />
                  </Pressable>
                ))
              )}
            </ScrollView>
          </View>
        </View>
      </Modal>
    </View>
  );
}

