import { MaterialIcons } from '@expo/vector-icons';
import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { 
  View, 
  Text, 
  StyleSheet, 
  ScrollView, 
  Pressable,
  TextInput,
  Modal,
  Alert,
} from 'react-native';
import { LinearGradient } from 'expo-linear-gradient';
import { typography, spacing, borderRadius, shadows } from '../../constants/designTokens';
import { useHostelStore, useTenantStore } from '../../src/stores';
import type { Bed } from '../../src/types/hostel.types';

// Admin Orange & Cream Theme
const THEME = {
  primary: '#EA580C',      // Burnt orange
  primaryDark: '#C2410C',  // Darker burnt orange  
  primaryLight: '#F97316', // Bright orange
  cream: '#FFFBF5',        // Warm cream
  creamLight: '#FFFDF9',   // Off-white
  white: '#FFFFFF',
  textPrimary: '#1F2937',
  textSecondary: '#6B7280',
  textMuted: '#9CA3AF',
  textInverse: '#FFFFFF',
  success: '#10B981',
  error: '#EF4444',
  warning: '#F59E0B',
  border: '#FED7AA',
};

export default function InfrastructureScreen() {
  const router = useRouter();
  const { 
    floors, 
    rooms, 
    beds, 
    fetchFloors, 
    fetchRooms, 
    fetchBeds,
    createFloor,
    createRoom,
    createBed,
    assignBed,
    vacateBed,
    currentHostel,
  } = useHostelStore();

  const { tenants, fetchTenants } = useTenantStore();

  const [selectedFloor, setSelectedFloor] = useState<string | null>(null);
  const [selectedRoom, setSelectedRoom] = useState<string | null>(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [modalType, setModalType] = useState<'floor' | 'room' | 'bed'>('floor');
  const [inputValue, setInputValue] = useState('');
  const [inputValue2, setInputValue2] = useState('');

  // Bed management modal state
  const [bedModalVisible, setBedModalVisible] = useState(false);
  const [selectedBed, setSelectedBed] = useState<Bed | null>(null);
  const [tenantModalVisible, setTenantModalVisible] = useState(false);

  useEffect(() => {
    if (currentHostel) {
      fetchFloors(currentHostel.id);
      fetchTenants(currentHostel.id);
    }
  }, [currentHostel]);

  useEffect(() => {
    if (selectedFloor) {
      fetchRooms(selectedFloor);
    }
  }, [selectedFloor]);

  useEffect(() => {
    if (selectedRoom) {
      fetchBeds(selectedRoom);
    }
  }, [selectedRoom]);

  const handleAdd = async () => {
    if (modalType === 'floor' && currentHostel) {
      await createFloor(currentHostel.id, { 
        floorNumber: parseInt(inputValue) || floors.length + 1,
        name: inputValue2 || `Floor ${inputValue}` 
      });
    } else if (modalType === 'room' && selectedFloor) {
      await createRoom(selectedFloor, { 
        roomNumber: inputValue,
        roomType: 'double' 
      });
    } else if (modalType === 'bed' && selectedRoom) {
      await createBed(selectedRoom, { 
        bedNumber: inputValue,
        price: parseInt(inputValue2) || 8000 
      });
    }
    setModalVisible(false);
    setInputValue('');
    setInputValue2('');
  };

  const openModal = (type: 'floor' | 'room' | 'bed') => {
    setModalType(type);
    setModalVisible(true);
  };

  // Handle bed card press - show action modal
  const handleBedPress = (bed: Bed) => {
    setSelectedBed(bed);
    setBedModalVisible(true);
  };

  // Handle vacate bed
  const handleVacateBed = async () => {
    if (!selectedBed) return;

    Alert.alert(
      'Vacate Bed',
      `Are you sure you want to vacate Bed ${selectedBed.bedNumber}?`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Vacate',
          style: 'destructive',
          onPress: async () => {
            try {
              console.log('Vacating bed:', selectedBed.id);
              await vacateBed(selectedBed.id);
              // Refresh beds data to ensure UI is up to date
              if (selectedRoom) {
                await fetchBeds(selectedRoom);
              }
              setBedModalVisible(false);
              setSelectedBed(null);
              // Show success feedback
              Alert.alert('Success', `Bed ${selectedBed.bedNumber} has been vacated successfully`);
            } catch (error) {
              console.error('Vacate error:', error);
              Alert.alert('Error', 'Failed to vacate bed');
            }
          }
        },
      ]
    );
  };

  // Handle assign bed - show tenant selection modal
  const handleAssignBed = () => {
    setTenantModalVisible(true);
    setBedModalVisible(false);
  };

  // Assign bed to selected tenant
  const handleSelectTenant = async (tenantId: string) => {
    if (!selectedBed) return;

    try {
      await assignBed(selectedBed.id, tenantId);
      if (selectedRoom) {
        await fetchBeds(selectedRoom);
      }
      setTenantModalVisible(false);
      setSelectedBed(null);
      Alert.alert('Success', `Bed ${selectedBed.bedNumber} assigned successfully`);
    } catch (error) {
      Alert.alert('Error', 'Failed to assign bed');
    }
  };

  // Close all modals
  const closeBedModal = () => {
    setBedModalVisible(false);
    setSelectedBed(null);
  };

  const closeTenantModal = () => {
    setTenantModalVisible(false);
    setSelectedBed(null);
  };

  // Get available tenants (those without an assigned bed)
  const getAvailableTenants = () => {
    const assignedBedIds = new Set(beds.filter(b => b.tenantId).map(b => b.tenantId));
    return tenants.filter(t => !assignedBedIds.has(t.id) && t.status === 'active');
  };

  // If no hostel is selected, show selection prompt
  if (!currentHostel) {
    return (
      <View style={styles.container}>
        <LinearGradient
          colors={[THEME.primary, THEME.primaryDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.header}
