const THEME = {
  primary: '#EA580C',      // Burnt orange
  primaryDark: '#C2410C',  // Darker burnt orange  
  primaryLight: '#F97316', // Bright orange
  cream: '#FFFBF5',        // Warm cream
  creamLight: '#FFFDF9',   // Off-white
  white: '#FFFFFF',
  textPrimary: '#1F2937',
  textSecondary: '#6B7280',
  textMuted: '#9CA3AF',
  textInverse: '#FFFFFF',
  success: '#10B981',
  error: '#EF4444',
  warning: '#F59E0B',
  border: '#FED7AA',
};

// Tenant Type
type Tenant = {
  id: string;
  name: string;
  phone: string;
  floor: string;
  room: string;
  paid: boolean;
  bedNumber?: string;
  joinDate?: string;
};

// Tenant Card Component
const TenantCard = ({
  tenant,
  onTogglePayment,
  onContact,
  onVacate,
}: {
  tenant: Tenant;
  onTogglePayment: () => void;
  onContact: () => void;
  onVacate: () => void;
}) => (
  <View style={styles.tenantCard}>
    {/* Header with name and status */}
    <View style={styles.tenantHeader}>
      <View style={styles.tenantInfo}>
        <View style={styles.avatar}>
          <Text style={styles.avatarText}>{tenant.name.charAt(0).toUpperCase()}</Text>
        </View>
        <View>
          <Text style={styles.tenantName}>{tenant.name}</Text>
          <Text style={styles.tenantMeta}>{tenant.floor} • {tenant.room}</Text>
        </View>
      </View>
      <View style={[styles.statusBadge, tenant.paid ? styles.statusPaid : styles.statusPending]}>
        <Text style={[styles.statusText, tenant.paid ? styles.statusPaidText : styles.statusPendingText]}>
          {tenant.paid ? 'Paid' : 'Pending'}
        </Text>
      </View>
    </View>

    {/* Contact Info */}
    <View style={styles.contactSection}>
      <Ionicons name="call-outline" size={16} color={THEME.textSecondary} />
      <Text style={styles.contactText}>{tenant.phone}</Text>
    </View>

    {/* Action Buttons */}
    <View style={styles.actionButtons}>
      <TouchableOpacity
        onPress={onContact}
        style={[styles.actionBtn, styles.contactBtn]}
      >
        <Ionicons name="chatbubble-outline" size={16} color={THEME.primary} />
        <Text style={styles.contactBtnText}>Contact</Text>
      </TouchableOpacity>

      <TouchableOpacity
        onPress={onTogglePayment}
        style={[styles.actionBtn, tenant.paid ? styles.pendingBtn : styles.paidBtn]}
      >
        <Ionicons
          name={tenant.paid ? "close-circle-outline" : "checkmark-circle-outline"}
          size={16}
          color={tenant.paid ? THEME.error : THEME.success}
        />
        <Text style={[styles.actionBtnText, tenant.paid ? styles.pendingBtnText : styles.paidBtnText]}>
          {tenant.paid ? 'Mark Pending' : 'Mark Paid'}
        </Text>
      </TouchableOpacity>

      <TouchableOpacity
        onPress={onVacate}
        style={[styles.actionBtn, styles.vacateBtn]}
      >
        <Ionicons name="log-out-outline" size={16} color={THEME.error} />
        <Text style={styles.vacateBtnText}>Vacate</Text>
      </TouchableOpacity>
    </View>
  </View>
);

// Add Tenant Modal
const AddTenantModal = ({
  visible,
  onClose,
  onAddTenant,
}: {
  visible: boolean;
  onClose: () => void;
  onAddTenant: (tenant: Omit<Tenant, 'id'>) => void;
}) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [floor, setFloor] = useState('');
  const [room, setRoom] = useState('');
  const [bedNumber, setBedNumber] = useState('');

  const handleAdd = () => {
    if (!name || !phone || !floor || !room) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }
    onAddTenant({ name, phone, floor, room, paid: false, bedNumber, joinDate: new Date().toISOString().split('T')[0] });
    setName(''); setPhone(''); setFloor(''); setRoom(''); setBedNumber('');
    onClose();
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View style={styles.modalOverlay}>
        <View style={styles.modalContent}>
          <View style={styles.modalHeader}>
            <Text style={styles.modalTitle}>Add New Tenant</Text>
            <TouchableOpacity onPress={onClose} style={styles.closeBtn}>
              <Ionicons name="close" size={24} color={THEME.textSecondary} />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Full Name *</Text>
              <TextInput
                placeholder="Enter tenant name"
                placeholderTextColor={THEME.textMuted}
                value={name}
                onChangeText={setName}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Phone Number *</Text>
              <TextInput
                placeholder="Enter phone number"
                placeholderTextColor={THEME.textMuted}
                value={phone}
                onChangeText={setPhone}
                keyboardType="phone-pad"
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Floor *</Text>
              <TextInput
                placeholder="e.g., Floor 1"
                placeholderTextColor={THEME.textMuted}
                value={floor}
                onChangeText={setFloor}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Room Number *</Text>
              <TextInput
                placeholder="e.g., Room 101"
                placeholderTextColor={THEME.textMuted}
                value={room}
                onChangeText={setRoom}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Bed Number (Optional)</Text>
              <TextInput
                placeholder="e.g., Bed A"
                placeholderTextColor={THEME.textMuted}
                value={bedNumber}
                onChangeText={setBedNumber}
                style={styles.input}
              />
            </View>
          </ScrollView>

          <View style={styles.modalButtons}>
            <TouchableOpacity onPress={onClose} style={[styles.modalBtn, styles.cancelBtn]}>
              <Text style={styles.cancelBtnText}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={handleAdd} style={[styles.modalBtn, styles.addBtn]}>
              <Text style={styles.addBtnText}>Add Tenant</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
};

// Stats Card Component
const StatsCard = ({ title, value, icon, color }: { title: string; value: number; icon: string; color: string }) => (
  <View style={[styles.statsCard, { borderLeftColor: color }]}>
    <View style={[styles.statsIconContainer, { backgroundColor: color + '15' }]}>
      <Ionicons name={icon as any} size={20} color={color} />
    </View>
    <View>
      <Text style={styles.statsValue}>{value}</Text>
      <Text style={styles.statsTitle}>{title}</Text>
    </View>
  </View>
);

export default function TenantsScreen() {
  const [tenants, setTenants] = useState<Tenant[]>([
    { id: '1', name: 'Shin', phone: '9876543210', floor: 'Floor 1', room: 'Room 101', paid: true, bedNumber: 'Bed A', joinDate: '2024-01-15' },
    { id: '2', name: 'Shan', phone: '9876543211', floor: 'Floor 1', room: 'Room 102', paid: false, bedNumber: 'Bed B', joinDate: '2024-02-01' },
    { id: '3', name: 'Dorae', phone: '9876543212', floor: 'Floor 2', room: 'Room 201', paid: true, bedNumber: 'Bed A', joinDate: '2024-01-20' },
    { id: '4', name: 'Mon', phone: '9876543213', floor: 'Floor 2', room: 'Room 202', paid: false, bedNumber: 'Bed B', joinDate: '2024-02-10' },
  ]);

  const [floorFilter, setFloorFilter] = useState<string>('All');
  const [statusFilter, setStatusFilter] = useState<string>('All');
  const [modalVisible, setModalVisible] = useState(false);

  // Unique floors
  const floors = ['All', ...Array.from(new Set(tenants.map(t => t.floor)))];

  // Filtered tenants
  const filteredTenants = tenants.filter(t => {
    const floorMatch = floorFilter === 'All' || t.floor === floorFilter;
    const statusMatch = statusFilter === 'All' || (statusFilter === 'Paid' ? t.paid : !t.paid);
    return floorMatch && statusMatch;
  });

  // Stats
  const totalTenants = tenants.length;
  const paidCount = tenants.filter(t => t.paid).length;
  const pendingCount = totalTenants - paidCount;

  const togglePayment = (index: number) => {
    const updated = [...tenants];
    updated[index].paid = !updated[index].paid;
    setTenants(updated);
  };

  const contactTenant = (tenant: Tenant) => {
    Alert.alert('Contact Tenant', `Contact ${tenant.name} at ${tenant.phone}`);
  };

  const vacateTenant = (tenant: Tenant, index: number) => {
    Alert.alert(
      'Vacate Tenant',
      `Are you sure you want to vacate ${tenant.name} from ${tenant.room}?`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Vacate',
          style: 'destructive',
          onPress: () => {
            const updated = tenants.filter((_, i) => i !== index);
            setTenants(updated);
            Alert.alert('Success', `${tenant.name} has been vacated successfully`);
          }
        }
      ]
    );
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <LinearGradient
        colors={[THEME.primary, THEME.primaryDark]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <MaterialIcons name="people" size={24} color={THEME.textInverse} />
          <Text style={styles.headerTitle}>Tenants</Text>
        </View>
        <Text style={styles.headerSubtitle}>Manage hostel tenants</Text>
      </LinearGradient>

      <ScrollView style={styles.scrollView} contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        {/* Stats Section */}
        <View style={styles.statsContainer}>
          <StatsCard title="Total" value={totalTenants} icon="people" color={THEME.primary} />
          <StatsCard title="Paid" value={paidCount} icon="checkmark-circle" color={THEME.success} />
          <StatsCard title="Pending" value={pendingCount} icon="time" color={THEME.error} />
        </View>

        {/* Add Tenant Button */}
        <TouchableOpacity onPress={() => setModalVisible(true)} style={styles.addTenantBtn}>
          <Ionicons name="add-circle" size={20} color={THEME.textInverse} />
          <Text style={styles.addTenantBtnText}>Add New Tenant</Text>
        </TouchableOpacity>

        <AddTenantModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          onAddTenant={(tenant) => setTenants(prev => [...prev, { ...tenant, id: Date.now().toString() }])}
        />

        {/* Filters */}
        <View style={styles.filtersContainer}>
          {/* Floor Filter */}
          <View style={styles.filterSection}>
            <Text style={styles.filterLabel}>Floor Filter</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false}>
              {floors.map(f => (
                <TouchableOpacity
                  key={f}
                  onPress={() => setFloorFilter(f)}
                  style={[styles.filterChip, floorFilter === f && styles.filterChipActive]}
                >
                  <Text style={[styles.filterChipText, floorFilter === f && styles.filterChipTextActive]}>
                    {f}
                  </Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          </View>

          {/* Status Filter */}
          <View style={styles.filterSection}>
            <Text style={styles.filterLabel}>Payment Status</Text>
            <View style={styles.statusFilters}>
              {['All', 'Paid', 'Pending'].map((status) => (
                <TouchableOpacity
                  key={status}
                  onPress={() => setStatusFilter(status)}
                  style={[styles.statusChip, statusFilter === status && styles.statusChipActive]}
                >
                  <Text style={[styles.statusChipText, statusFilter === status && styles.statusChipTextActive]}>
                    {status}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        </View>

        {/* Tenant Cards */}
        <View style={styles.tenantsSection}>
          <Text style={styles.sectionTitle}>
            {filteredTenants.length} Tenant{filteredTenants.length !== 1 ? 's' : ''}
          </Text>

          {filteredTenants.length > 0 ? (
            filteredTenants.map((tenant) => (
              <TenantCard
                key={tenant.id}
                tenant={tenant}
                onTogglePayment={() => togglePayment(tenants.indexOf(tenant))}
                onContact={() => contactTenant(tenant)}
                onVacate={() => vacateTenant(tenant, tenants.indexOf(tenant))}
              />
            ))
          ) : (
            <View style={styles.emptyState}>
              <Ionicons name="people-outline" size={48} color={THEME.textMuted} />
              <Text style={styles.emptyTitle}>No tenants found</Text>
              <Text style={styles.emptySubtitle}>Try adjusting your filters or add a new tenant</Text>
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  );
}

