// Photo Upload Component
const PhotoUploadField = ({
  label,
  photoUri,
  onSelectPhoto,
}: {
  label: string;
  photoUri: string | null;
  onSelectPhoto: (uri: string) => void;
}) => {
  const pickImage = async () => {
    const { status } = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert('Permission Required', 'Please grant camera roll permissions to upload photos.');
      return;
    }

    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      allowsEditing: true,
      aspect: [4, 3],
      quality: 0.8,
    });

    if (!result.canceled && result.assets && result.assets.length > 0) {
      onSelectPhoto(result.assets[0].uri);
    }
  };

  return (
    <View style={styles.inputGroup}>
      <Text style={styles.inputLabel}>{label}</Text>
      <TouchableOpacity onPress={pickImage} style={styles.photoUploadContainer}>
        {photoUri ? (
          <Image source={{ uri: photoUri }} style={styles.photoPreview} />
        ) : (
          <View style={styles.photoPlaceholder}>
            <Ionicons name="camera-outline" size={32} color={THEME.textMuted} />
            <Text style={styles.photoPlaceholderText}>Tap to upload photo</Text>
          </View>
        )}
      </TouchableOpacity>
    </View>
  );
};

// Add Tenant Modal
const AddTenantModal = ({
  visible,
  onClose,
  onAddTenant,
}: {
  visible: boolean;
  onClose: () => void;
  onAddTenant: (tenant: Omit<Tenant, 'id'>) => void;
}) => {
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [aadhaarCard, setAadhaarCard] = useState('');
  const [aadhaarCardPhoto, setAadhaarCardPhoto] = useState<string | null>(null);
  const [candidatePhoto, setCandidatePhoto] = useState<string | null>(null);
  const [parentOrGuardian, setParentOrGuardian] = useState('');
  const [homeAddress, setHomeAddress] = useState('');

  const handleAdd = () => {
    if (!name || !phone || !aadhaarCard || !parentOrGuardian || !homeAddress) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }
    onAddTenant({ 
      name, 
      phone, 
      photo: candidatePhoto || undefined,
      aadhaarCard, 
      aadhaarCardPhoto: aadhaarCardPhoto || undefined,
      parentOrGuardian, 
      homeAddress,
      paid: false, 
      joinDate: new Date().toISOString().split('T')[0] 
    });
    setName(''); 
    setPhone(''); 
    setAadhaarCard(''); 
    setAadhaarCardPhoto(null);
    setCandidatePhoto(null);
    setParentOrGuardian(''); 
    setHomeAddress('');
    onClose();
  };

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View style={styles.modalOverlay}>
        <View style={styles.modalContent}>
          <View style={styles.modalHeader}>
            <Text style={styles.modalTitle}>Add New Tenant</Text>
            <TouchableOpacity onPress={onClose} style={styles.closeBtn}>
              <Ionicons name="close" size={24} color={THEME.textSecondary} />
            </TouchableOpacity>
          </View>

          <ScrollView showsVerticalScrollIndicator={false}>
            {/* Candidate Photo Upload */}
            <PhotoUploadField
              label="Candidate Photo"
              photoUri={candidatePhoto}
              onSelectPhoto={setCandidatePhoto}
            />

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Full Name *</Text>
              <TextInput
                placeholder="Enter tenant name"
                placeholderTextColor={THEME.textMuted}
                value={name}
                onChangeText={setName}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Phone Number *</Text>
              <TextInput
                placeholder="Enter phone number"
                placeholderTextColor={THEME.textMuted}
                value={phone}
                onChangeText={setPhone}
                keyboardType="phone-pad"
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Aadhaar Card Number *</Text>
              <TextInput
                placeholder="Enter 12-digit Aadhaar number"
                placeholderTextColor={THEME.textMuted}
                value={aadhaarCard}
                onChangeText={setAadhaarCard}
                keyboardType="numeric"
                maxLength={12}
                style={styles.input}
              />
            </View>

            {/* Aadhaar Card Photo Upload */}
            <PhotoUploadField
              label="Aadhaar Card Photo *"
              photoUri={aadhaarCardPhoto}
              onSelectPhoto={setAadhaarCardPhoto}
            />

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Parent / Guardian Name *</Text>
              <TextInput
                placeholder="Enter parent or guardian name"
                placeholderTextColor={THEME.textMuted}
                value={parentOrGuardian}
                onChangeText={setParentOrGuardian}
                style={styles.input}
              />
            </View>

            <View style={styles.inputGroup}>
              <Text style={styles.inputLabel}>Home Address *</Text>
              <TextInput
                placeholder="Enter complete home address"
                placeholderTextColor={THEME.textMuted}
                value={homeAddress}
                onChangeText={setHomeAddress}
                multiline
                numberOfLines={3}
                style={[styles.input, styles.textArea]}
              />
            </View>
          </ScrollView>

          <View style={styles.modalButtons}>
            <TouchableOpacity onPress={onClose} style={[styles.modalBtn, styles.cancelBtn]}>
              <Text style={styles.cancelBtnText}>Cancel</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={handleAdd} style={[styles.modalBtn, styles.addBtn]}>
              <Text style={styles.addBtnText}>Add Tenant</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
};

