);

export default function TenantsScreen() {
  const router = useRouter();
  const { currentHostel } = useHostelStore();

  // If no hostel is selected, show selection prompt
  if (!currentHostel) {
    return (
      <View style={styles.container}>
        <LinearGradient
          colors={[THEME.primary, THEME.primaryDark]}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={styles.header}
        >
          <View style={styles.headerContent}>
            <MaterialIcons name="people" size={24} color={THEME.textInverse} />
            <Text style={styles.headerTitle}>Tenants</Text>
          </View>
        </LinearGradient>

        <View style={styles.noHostelContainer}>
          <MaterialIcons name="apartment" size={64} color={THEME.textMuted} />
          <Text style={styles.noHostelTitle}>No Hostel Selected</Text>
          <Text style={styles.noHostelSubtitle}>
            Please select a hostel to view and manage tenants
          </Text>
          <TouchableOpacity
            style={styles.selectHostelBtn}
            onPress={() => router.push('/admin/hostels' as never)}
          >
            <LinearGradient
              colors={[THEME.primary, THEME.primaryLight]}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 0 }}
              style={styles.selectHostelGradient}
            >
              <MaterialIcons name="apartment" size={20} color={THEME.white} />
              <Text style={styles.selectHostelText}>Select Hostel</Text>
            </LinearGradient>
          </TouchableOpacity>
        </View>
      </View>
    );
  }

  const [tenants, setTenants] = useState<Tenant[]>([
    { id: '1', name: 'Shin', phone: '9876543210', aadhaarCard: '123456789012', parentOrGuardian: 'Mr. Kumar', homeAddress: '123 Main St, Bangalore, Karnataka', paid: true, joinDate: '2024-01-15' },
    { id: '2', name: 'Shan', phone: '9876543211', aadhaarCard: '234567890123', parentOrGuardian: 'Mrs. Sharma', homeAddress: '456 Park Ave, Mumbai, Maharashtra', paid: false, joinDate: '2024-02-01' },
    { id: '3', name: 'Dorae', phone: '9876543212', aadhaarCard: '345678901234', parentOrGuardian: 'Mr. Reddy', homeAddress: '789 Lake View, Hyderabad, Telangana', paid: true, joinDate: '2024-01-20' },
    { id: '4', name: 'Mon', phone: '9876543213', aadhaarCard: '456789012345', parentOrGuardian: 'Mrs. Patel', homeAddress: '321 Hill Road, Pune, Maharashtra', paid: false, joinDate: '2024-02-10' },
  ]);

  const [statusFilter, setStatusFilter] = useState<string>('All');
  const [modalVisible, setModalVisible] = useState(false);

  // Filtered tenants
  const filteredTenants = tenants.filter(t => {
    const statusMatch = statusFilter === 'All' || (statusFilter === 'Paid' ? t.paid : !t.paid);
    return statusMatch;
  });

  // Stats
  const totalTenants = tenants.length;
  const paidCount = tenants.filter(t => t.paid).length;
  const pendingCount = totalTenants - paidCount;

  const togglePayment = (index: number) => {
    const updated = [...tenants];
    updated[index].paid = !updated[index].paid;
    setTenants(updated);
  };

  const contactTenant = (tenant: Tenant) => {
    Alert.alert('Contact Tenant', `Contact ${tenant.name} at ${tenant.phone}`);
  };

  const vacateTenant = (tenant: Tenant, index: number) => {
    Alert.alert(
      'Vacate Tenant',
      `Are you sure you want to vacate ${tenant.name}?`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Vacate',
          style: 'destructive',
          onPress: () => {
            const updated = tenants.filter((_, i) => i !== index);
            setTenants(updated);
            Alert.alert('Success', `${tenant.name} has been vacated successfully`);
          }
        }
      ]
    );
  };

  return (
    <View style={styles.container}>
      {/* Header */}
      <LinearGradient
        colors={[THEME.primary, THEME.primaryDark]}
        start={{ x: 0, y: 0 }}
        end={{ x: 1, y: 1 }}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <MaterialIcons name="people" size={24} color={THEME.textInverse} />
          <Text style={styles.headerTitle}>Tenants</Text>
        </View>
        <Text style={styles.headerSubtitle}>Manage hostel tenants</Text>
      </LinearGradient>

      <ScrollView style={styles.scrollView} contentContainerStyle={styles.scrollContent} showsVerticalScrollIndicator={false}>
        {/* Stats Section */}
        <View style={styles.statsContainer}>
          <StatsCard title="Total" value={totalTenants} icon="people" color={THEME.primary} />
          <StatsCard title="Paid" value={paidCount} icon="checkmark-circle" color={THEME.success} />
          <StatsCard title="Pending" value={pendingCount} icon="time" color={THEME.error} />
        </View>

        {/* Add Tenant Button */}
        <TouchableOpacity onPress={() => setModalVisible(true)} style={styles.addTenantBtn}>
          <Ionicons name="add-circle" size={20} color={THEME.textInverse} />
          <Text style={styles.addTenantBtnText}>Add New Tenant</Text>
        </TouchableOpacity>

        <AddTenantModal
          visible={modalVisible}
          onClose={() => setModalVisible(false)}
          onAddTenant={(tenant) => setTenants(prev => [...prev, { ...tenant, id: Date.now().toString() }])}
        />

        {/* Filters */}
        <View style={styles.filtersContainer}>
          {/* Status Filter */}
          <View style={styles.filterSection}>
            <Text style={styles.filterLabel}>Payment Status</Text>
            <View style={styles.statusFilters}>
              {['All', 'Paid', 'Pending'].map((status) => (
                <TouchableOpacity
                  key={status}
                  onPress={() => setStatusFilter(status)}
                  style={[styles.statusChip, statusFilter === status && styles.statusChipActive]}
                >
                  <Text style={[styles.statusChipText, statusFilter === status && styles.statusChipTextActive]}>
                    {status}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
          </View>
        </View>

        {/* Tenant Cards */}
        <View style={styles.tenantsSection}>
          <Text style={styles.sectionTitle}>
            {filteredTenants.length} Tenant{filteredTenants.length !== 1 ? 's' : ''}
          </Text>

          {filteredTenants.length > 0 ? (
            filteredTenants.map((tenant) => (
              <TenantCard
                key={tenant.id}
                tenant={tenant}
                onTogglePayment={() => togglePayment(tenants.indexOf(tenant))}
                onContact={() => contactTenant(tenant)}
                onVacate={() => vacateTenant(tenant, tenants.indexOf(tenant))}
              />
            ))
          ) : (
            <View style={styles.emptyState}>
              <Ionicons name="people-outline" size={48} color={THEME.textMuted} />
              <Text style={styles.emptyTitle}>No tenants found</Text>
              <Text style={styles.emptySubtitle}>Try adjusting your filters or add a new tenant</Text>
            </View>
          )}
        </View>
      </ScrollView>
    </View>
  );
}

